<?php use App\UI\UI as U; $s=$data['sample']; $by = fn($st) => (string)count(array_filter($s['applications'], fn($a) => $a['status'] === $st)); $tone = ['Pending'=>'amber','Approved'=>'green','Rejected'=>'red']; ?>
<?= U::heading('Station applications','Review station registration requests in Hamtic.') ?>
<div class="mb-5 grid grid-cols-2 gap-3 md:gap-4 lg:grid-cols-3 max-lg:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Applications',(string)count($s['applications']),'file','blue','All registration requests','Total') ?><?= U::stat('Pending',$by('Pending'),'clock','amber','Waiting for your review','Pending') ?><?= U::stat('Approved',$by('Approved'),'check','green','Listed on HydroRoute','Approved') ?></div>
<section class="panel p-4 md:p-5"><div class="mb-4 grid gap-3 md:grid-cols-[1fr_240px]"><?= U::field('Search applications','application-search','','search',['icon'=>'search','data-search'=>'application-list','placeholder'=>'Station, barangay or applicant']) ?><?= U::select('Registration status','application-filter',['all'=>'All applications','Pending'=>'Pending','Approved'=>'Approved','Rejected'=>'Rejected'],'all',['data-filter-target'=>'application-list']) ?></div>
<?php if ($s['applications'] === []): ?><div class="rounded-xl border border-dashed border-line bg-mist p-8 text-center"><span class="title-icon mx-auto bg-white"><?= U::icon('file','size-5') ?></span><p class="mt-3 font-semibold">No applications yet</p><p class="mt-1 text-sm text-muted">New station registrations from <a class="auth-link" href="/register-station">the registration page</a> appear here.</p></div><?php else: ?>
<div class="overflow-x-auto"><table class="data-table" id="application-list"><thead><tr><?php foreach(['Application','Station','Applicant','Applied','Status','Action'] as $h): ?><th><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($s['applications'] as $a): ?><tr data-search-row data-filter-value="<?= U::e($a['status']) ?>"><td class="whitespace-nowrap font-bold"><?= U::e($a['ref'] ?? $a['id']) ?></td><td><span class="block font-semibold"><?= U::e($a['name']) ?></span><span class="flex items-center gap-1 text-xs text-muted"><?= U::icon('pin','size-3.5') ?><?= U::e($a['area']) ?></span></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('user','size-4 text-muted') ?><?= U::e($a['applicant']) ?></span></td><td><span class="inline-flex items-center gap-1.5 whitespace-nowrap"><?= U::icon('calendar','size-4 text-muted') ?><?= U::e($a['date']) ?></span></td><td><?= U::badge($a['status'],$tone[$a['status']] ?? 'blue') ?></td><td><?= U::btn($a['status']==='Pending'?'Review':'View','/super-admin/application?id='.rawurlencode($a['id']),$a['status']==='Pending'?'primary':'secondary',$a['status']==='Pending'?'file':'eye',['class'=>'btn-sm']) ?></td></tr><?php endforeach; ?></tbody></table><p data-empty hidden class="p-5 text-center text-muted">No applications match these filters.</p></div><?php endif ?></section>
